      (1, 1636, 4, '7FD3D24C', '986990608', null, '2026-05-04', '2026-05-21 11:03:28', '2026-05-04', 36, 36, 'SERVICIOS ADUANEROS Y DE ALMACENAJE', 1006, 452.5, 1, 'V', 'JES', null, null, 'JES', '2026-05-21 00:00:00', 'V', 2026, 5, 22, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2026, null, 5, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null, 0, 0, 0, 0, 0, 0, 0, 0, 0, null, null, null, null, 'N', 0, null, null),
